      "productDocs.overview": "Product Overview",
      "productDocs.overviewDesc": "Claw Router is an enterprise-grade AI aggregation platform designed to simplify the integration, management, and scaling of foundation models. By providing a unified API, it eliminates vendor lock-in and reduces the complexity of building multimodal AI applications.",
