      "api.intro.title": "介绍",
      "api.intro.auth": "身份验证",
      "api.intro.errors": "错误",
      "api.intro.desc": "Claw Router API 基于 REST 架构。我们的 API 具有可预测的面向资源的 URL，接受 JSON 编码的请求体，返回 JSON 编码的响应，并使用标准的 HTTP 响应代码、身份验证和动词。我们为 LLM、嵌入、图像、视频、音频和音乐生成提供统一的接口。",
      "api.intro.authDesc1": "Claw Router API 使用 API 密钥进行身份验证。访问您的 API 密钥页面以检索您将在请求中使用的 API 密钥。",
      "api.intro.authDesc2": "请记住，您的 API 密钥是秘密！不要与他人共享，也不要将其暴露在任何客户端代码（浏览器、应用程序）中。生产请求必须通过您自己的后端服务器进行路由。",
      "api.intro.authHeader": "Authorization 请求头",
      "api.intro.errorsTitle": "错误",
      "api.intro.errorsDesc": "Claw Router 使用常规的 HTTP 响应代码来指示 API 请求的成功或失败。通常：2xx 范围内的代码表示成功。4xx 范围内的代码表示由于提供的信息而失败的错误。5xx 范围内的代码表示 Claw Router 服务器出现错误。",
      "api.intro.errorExample": "错误响应示例",
